#!/usr/bin/env bash
# Lance toutes les vérifications hors ligne (aucun réseau, aucun compte nécessaire) : bash outils/tests/tout.sh
set -u; cd "$(dirname "$0")/../.."; echec=0
etape() { echo "── $1"; shift; if "$@"; then :; else echec=1; fi; }
etape "Fichiers, liens, voix, règles de synthèse vocale" bash -c 'set -o pipefail; node outils/tests/verifier.mjs | tail -1'
etape "Droits (Créateur, invités, abonnés, gratuit)" bash -c 'set -o pipefail; node --test outils/tests/droits.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/droits.test.mjs >/dev/null 2>&1'
etape "Jetons Firebase (vérification serveur)" bash -c 'set -o pipefail; node --test outils/tests/jeton.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/jeton.test.mjs >/dev/null 2>&1'
etape "API (comptes, droits, invitations, admin, Stripe test, Premium, RGPD)" bash -c 'set -o pipefail; node --test --test-concurrency=1 outils/tests/api.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test --test-concurrency=1 outils/tests/api.test.mjs >/dev/null 2>&1'
etape "Premium (Créateur, Premium, Famille, Gratuit, anonyme, révocation, expiration, voir comme)" bash -c 'set -o pipefail; node --test --test-concurrency=1 outils/tests/premium.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test --test-concurrency=1 outils/tests/premium.test.mjs >/dev/null 2>&1'
etape "Grand Voyage : zones Premium fermées/ouvertes (données, sans rendu 3D)" bash -c 'set -o pipefail; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/voyage-regions.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/voyage-regions.test.mjs >/dev/null 2>&1'
etape "Missions : comportement figé (collecte, sac, livraison, récompenses, sauvegardes anciennes) + voix des textes de mission" bash -c 'set -o pipefail; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/missions-caracterisation.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/missions-caracterisation.test.mjs >/dev/null 2>&1'
etape "Habitants : registre, Loumi indépendante de Nour et des missions (dialogues, mémoire, code), Nour facultatif" bash -c 'set -o pipefail; node --test outils/tests/habitants-loumi.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/habitants-loumi.test.mjs >/dev/null 2>&1'
etape "Interface contextuelle (HUD) : apparaît puis s'efface, défilement des panneaux" bash -c 'set -o pipefail; node --test outils/tests/hud.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/hud.test.mjs >/dev/null 2>&1'
etape "Script local du rôle Créateur" bash -c 'set -o pipefail; node --test outils/tests/role-createur.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/role-createur.test.mjs >/dev/null 2>&1'
etape "Firestore REST (requêtes, conversions, compte de service)" bash -c 'set -o pipefail; node --test outils/tests/firestore.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/firestore.test.mjs >/dev/null 2>&1'
etape "Restauration de la base des comptes (export → age → import → API)" bash -c 'set -o pipefail; node --test outils/tests/restauration.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/restauration.test.mjs >/dev/null 2>&1'
etape "Garde-fou de branche (main refusée)" bash -c 'set -o pipefail; node --test outils/tests/garde-branche.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/garde-branche.test.mjs >/dev/null 2>&1'
etape "Outil de bascule Cloudflare (fausse API : sauvegarde DNS, MX/TXT intacts, rétablissement, retour en arrière)" bash -c 'set -o pipefail; node --test outils/tests/bascule-cloudflare.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/bascule-cloudflare.test.mjs >/dev/null 2>&1'
etape "Comparaison des zones DNS (messagerie : un MX / SPF / DKIM oublié est détecté)" bash -c 'set -o pipefail; node --test outils/tests/comparer-zones.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/comparer-zones.test.mjs >/dev/null 2>&1'
etape "Envoi du pack vers R2 (simulation, garde-fous)" bash -c 'set -o pipefail; node --test outils/tests/envoi-r2.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/envoi-r2.test.mjs >/dev/null 2>&1'
etape "Configuration : outil de contrôle" bash -c 'set -o pipefail; node --test outils/tests/verifier-configuration.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/verifier-configuration.test.mjs >/dev/null 2>&1'
etape "Vérificateur de la configuration Firebase (fausse API)" bash -c 'set -o pipefail; node --test outils/tests/verifier-firebase.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/verifier-firebase.test.mjs >/dev/null 2>&1'
etape "Vérificateur des règles Firestore (fausse API)" bash -c 'set -o pipefail; node --test outils/tests/verifier-firestore.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/verifier-firestore.test.mjs >/dev/null 2>&1'
etape "Soins des montures : besoins jamais punitifs, récompenses limitées, poses 3D" bash -c 'set -o pipefail; node --test outils/tests/soins.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/soins.test.mjs >/dev/null 2>&1'
etape "Veille de Loumi : rappels fondés sur les vrais besoins, discrets, sans répétition" bash -c 'set -o pipefail; node --test outils/tests/veille.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/veille.test.mjs >/dev/null 2>&1'
etape "Chasse aux mots : niveaux, âges, étoiles sans punition, sauvegarde, 160 audios associés aux dialogues" bash -c 'set -o pipefail; node --test outils/tests/chasse-mots.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/chasse-mots.test.mjs >/dev/null 2>&1'
etape "Mystères du désert : 7 chapitres, énigmes toujours solvables, progression, 70 audios associés" bash -c 'set -o pipefail; node --test outils/tests/mysteres.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/mysteres.test.mjs >/dev/null 2>&1'
etape "Quiz de Nour : 96 questions vérifiées, réponses mélangées, étoiles sans punition, 213 audios associés" bash -c 'set -o pipefail; node --test outils/tests/quiz.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/quiz.test.mjs >/dev/null 2>&1'
etape "Voix des jeux : seules les 10 voix Nour, aucune voix extérieure, garde-fou de production" bash -c 'set -o pipefail; node --test outils/tests/voix-autorisees.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/voix-autorisees.test.mjs >/dev/null 2>&1'
etape "Enclos de l'écurie : places stables, allée dégagée, trajet par l'entrée" bash -c 'set -o pipefail; node --test outils/tests/enclos.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/enclos.test.mjs >/dev/null 2>&1'
etape "Page Tarifs : promesses = catalogue" bash -c 'set -o pipefail; node --test outils/tests/tarifs.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/tarifs.test.mjs >/dev/null 2>&1'
etape "Ablutions : l'intention d'abord (page, jeux, 3D)" bash -c 'set -o pipefail; node --test outils/tests/ablutions.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/ablutions.test.mjs >/dev/null 2>&1'
etape "Voix (Ablutions, Prière, Calendrier) : toutes validées par le client, présentes, bonne durée" bash -c 'set -o pipefail; node --test outils/tests/voix-verifiees.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/voix-verifiees.test.mjs >/dev/null 2>&1' 
etape "Portail du Monde de Nour : règles (une fois par session, voix et portes synchronisées, profil enfant sans écrasement)" bash -c 'set -o pipefail; node --test outils/tests/portail-logique.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/portail-logique.test.mjs >/dev/null 2>&1'
etape "Mode sans visage : garde-fous (pièces de visage étiquetées, SVG, GLB, pages, texte des parents, API de la famille)" bash -c 'set -o pipefail; node --test outils/tests/sans-visage-garde.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/sans-visage-garde.test.mjs >/dev/null 2>&1' 
if node -e "require.resolve('three/package.json')" 2>/dev/null || [ -d /home/user/node_modules/three ]; then etape "Personnages 3D N1 (vrai modèle, vrai moteur, secours)" bash -c 'set -o pipefail; node --test personnages3d/*.test.js 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test personnages3d/*.test.js >/dev/null 2>&1'; else echo "── Personnages 3D N1 : SAUTÉ (three@0.170.0 non installé hors dépôt : cd .. && npm i three@0.170.0)"; fi
etape "Parcours de compte complet (serveur local, simulation)" bash -c 'set -o pipefail; S=$(bash outils/tests/parcours-reel.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 échoués"'
etape "Dossier publié (aucune fuite)" bash -c 'set -o pipefail; node outils/construire.mjs >/dev/null && node outils/tests/verifier-dist.mjs | tail -1'
etape "Aucune fuite Premium (dépôt public + dist)" bash -c 'set -o pipefail; node outils/tests/fuite-premium.mjs | tail -1; node outils/tests/fuite-premium.mjs >/dev/null'
etape "Exercice de restauration chiffrée" bash -c 'set -o pipefail; bash outils/sauvegarde/exercice-restauration.sh | tail -1'
etape "Secrets : configuration invalide sans fuite" bash -c 'set -o pipefail; node --test outils/tests/secrets.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/secrets.test.mjs >/dev/null 2>&1'
if [ "${EMULATEURS_FIREBASE:-0}" = 1 ]; then etape "Émulateurs officiels Firebase : règles, base REST, restauration, rôle Créateur" bash -c 'set -o pipefail; bash outils/tests/emulateurs-firebase.sh | grep -E "^(── |not ok|# (tests|pass|fail))"'; fi
if [ "${NAVIGATEUR:-0}" = 1 ]; then etape "Service worker du calendrier (hors-ligne, purge, aucune donnée privée en cache)" bash -c 'set -o pipefail; bash outils/tests/pwa.sh | grep -E "tests réussis"'; etape "Parcours complets dans Chrome (émulateur local)" bash -c 'set -o pipefail; bash outils/tests/parcours.sh | grep -E "réussis"'; etape "Compte visible dans Chrome : visiteur, inscription, retour automatique, session, déconnexion, Google (simulé), protections" bash -c 'set -o pipefail; S=$(bash outils/tests/parcours-compte-visible.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 échoués"'; etape "Bloc 3 dans Chrome : Premium, Chasse aux mots, aperçu Créateur, ordinateur + téléphone" bash -c 'bash outils/tests/parcours-bloc3.sh | tail -1'; etape "Portail du Monde de Nour dans Chrome : parent → enfant → portail → monde → progression (ordinateur + téléphone)" bash -c 'set -o pipefail; S=$(bash outils/tests/portail.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 en échec"'; etape "Mode sans visage dans Chrome : visiteur, 3D (enfants, montures, animaux, GLB), compte, déconnexion/reconnexion (ordinateur + téléphone)" bash -c 'set -o pipefail; S=$(bash outils/tests/sans-visage.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 en échec"'; etape "Amélioration des personnages (version de test) : expressions, animations, compatibilité mode sans visage, originaux intacts" bash -c 'set -o pipefail; S=$(bash outils/tests/amelioration-personnages.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 en échec"'; fi
[ $echec -eq 0 ] && echo "TOUT EST VERT" || echo "AU MOINS UNE VÉRIFICATION A ÉCHOUÉ"; exit $echec
